    task_id: &str,
    channel: ForwardingChannel,
    token: &AttemptToken,
) -> bool {
    Arc::ptr_eq(&self.instance, &token.instance)
        && token.task_id == task_id
        && token.channel == channel
        && self.in_flight.get(&(task_id.to_owned(), channel)) == Some(token)
}

fn commit_mutation(&mut self, next: JsonDocument) -> Result<(), QueueMutationError> {
    let ciphertext = seal(&self.key, &next, self.limits).map_err(QueueMutationError::State)?;
    match atomic_replace(&self.path, &ciphertext) {
        Ok(()) => {
            self.current = next;
            Ok(())
        }
        Err(ReplaceError::BeforeCommit) => Err(QueueMutationError::StorageIo),
        Err(ReplaceError::AfterCommit) => {
            self.poisoned = true;
            Err(QueueMutationError::PersistenceUncertain)
        }
    }
}

fn ensure_usable(&self) -> Result<(), StateStoreError> {
    if self.poisoned {
        Err(StateStoreError::ReopenRequired)
    } else {
        Ok(())
    }
}

struct AttemptReservation {
    queue: Arc<Mutex<QueueStore>>,
    task_id: String,
    channel: ForwardingChannel,
    token: AttemptToken,
    releases: Arc<ReleaseLedger>,
}

impl AttemptReservation {
    fn new(
        queue: Arc<Mutex<QueueStore>>,
        task_id: &str,
        channel: ForwardingChannel,
        token: AttemptToken,
        releases: Arc<ReleaseLedger>,
    ) -> Self {
        Self {
            queue,
            task_id: task_id.to_owned(),
            channel,
            token,
            releases,
        }
    }
}

impl Drop for AttemptReservation {
    fn drop(&mut self) {
        if let Ok(mut queue) = self.queue.try_lock() {
            queue.release_destination(&self.task_id, self.channel, &self.token);
            return;
        }
        let Some(completion) = self.releases.register() else {
            return;
        };
        let job = ReleaseJob {
            queue: Some(self.queue.clone()),
            task_id: self.task_id.clone(),
            channel: self.channel,
            token: self.token.clone(),
            completion,
        };
        if let Ok(runtime) = tokio::runtime::Handle::try_current() {
            runtime.spawn(job.run());
        }
        // Without a runtime the owned job drops here and records a sticky
        // unconfirmed result; it never reports successful release.
    }
}

