fn release_provisional_if_any(&self, record: &Record) -> Result<(), &'static str> {
    #[cfg(test)]
    self.0.persistence_hooks.before_provisional_lock();
    let mut status = record.state.lock().unwrap_or_else(|e| e.into_inner());
    if !status.provisional {
        // Another stop may already have settled this provisional claim.
        // Ordinary started records also no-op here and still owe their
        // normal retained worker/RF join below in stop_before.
        return Ok(());
    }
    #[cfg(test)]
    if self.0.persistence_hooks.fail_release() {
        return Err("module_vowifi_cleanup_unconfirmed");
    }
    #[cfg(test)]
    self.0.persistence_hooks.note_actual_release();
    let released = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        record.claim.release_confirmed()
    }));
    if !matches!(released, Ok(Ok(()))) {
        return Err("module_vowifi_cleanup_unconfirmed");
    }
    status.provisional = false;
    status.cleanup_error = None;
    status.complete_cleanup();
    drop(status);
    record.completed.notify_waiters();
    Ok(())

    async fn stop(&mut self) -> Result<(), &'static str> {
        if let Some(result) = self.stop_result {
            return result;
        }
        self.retiring = true;
        self.queue_io.close();
        let _ = self.shutdown.send(true);
        if self.runner_result.is_none() {
            let result = match self.runner.as_mut() {
                Some(runner) => runner.await.map_err(|error| {
                    if error.is_panic() {
                        "sms_forwarding_runner_panicked"
                    } else {
                        "sms_forwarding_runner_aborted"
                    }
                }),
                None => Err("sms_forwarding_runner_unconfirmed"),
            };
            // No await between observing the join and retaining its outcome.
            self.runner = None;
            self.runner_result = Some(result);
        }
        // A joined runner may have synchronously registered a deferred Drop
        // release. Keep this generation and its Store/flock through the real
        // drain; cancelling this waiter leaves the observed join for next stop.
        // No queue guard is held while waiting for release completion.
        let io = self.queue_io.finish().await;
        let releases = self
            .worker
            .finish_releases()
            .await
            .map_err(|_| "sms_forwarding_release_unconfirmed");
        // Observe every owner even if an earlier result is an error.
        let result = self.runner_result.unwrap().and(io).and(releases);
        self.stop_result = Some(result);
        result
    }
}

fn retire(&self, error: Option<String>) {
    if let Some(error) = error {
        let mut diagnostics = self.diagnostics();
        if diagnostics.orphan_errors.len() < MAX_ORPHAN_ERRORS {
            diagnostics.orphan_errors.push(error);
        } else {
            diagnostics.omitted_errors = diagnostics.omitted_errors.saturating_add(1);
        }
    }
    if self
        .pending
        .fetch_update(Ordering::AcqRel, Ordering::Acquire, |count| {
            count.checked_sub(1)
        })
        .is_err()
    {
        self.accounting_failed.store(true, Ordering::Release);
        self.mark_unconfirmed();
    }
    self.changed.notify_waiters();
}

async fn finish_pending(&self) -> Result<(), String> {
    loop {
        let changed = self.changed.notified();
        tokio::pin!(changed);
        changed.as_mut().enable();
        if self.pending.load(Ordering::Acquire) == 0 {
            let diagnostics = self.diagnostics();
            let mut errors = Vec::new();
            if self.unconfirmed.load(Ordering::Acquire) {
                errors.push(
                    "archive completion unconfirmed: archive worker panicked, resource destruction or accounting uncertain"
                        .to_owned(),
                );
            }
            if !diagnostics.orphan_errors.is_empty() || diagnostics.omitted_errors != 0 {
                let mut orphan = diagnostics.orphan_errors.join("; ");
                if diagnostics.omitted_errors != 0 {
                    let qualifier = if diagnostics.omitted_errors == usize::MAX {
                        "at least "
                    } else {
                        ""
                    };
                    write!(
                        orphan,
                        "; {qualifier}{} further orphan archive failures",
                        diagnostics.omitted_errors
                    )
                    .expect("String formatting");
                }
                errors.push(format!("undelivered archive worker failure(s): {orphan}"));
            }
            return if errors.is_empty() {
                Ok(())
            } else {
                Err(errors.join("; "))
            };
        }
        changed.await;
    }
}

